import {totalFeet} from './estimator-core.mjs?v=3';
export const $=id=>document.getElementById(id);
export const money=n=>n===null?'Richard to quote':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);
export const el=(tag,text,className)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(className)n.className=className;return n;};
export async function api(url,options={}){const r=await fetch(url,{...options,headers:{'Content-Type':'application/json',...options.headers},signal:AbortSignal.timeout(20000)});if(!r.headers.get('content-type')?.includes('application/json'))throw Error('Please sign in to the staff inbox, or check that Cloudflare is connected.');const data=await r.json();if(!r.ok)throw Error(data.error||'Unable to load this request.');return data;}
export function draw(plan,target){target.replaceChildren();if(plan.mode==='manual'){target.append(el('p','Customer entered footage manually. No measured map is attached.'));return;}
 const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 800 500');svg.setAttribute('role','img');svg.setAttribute('aria-label','Submitted fence layout and gate locations');
 const shape=(tag,attrs,text)=>{const n=document.createElementNS(ns,tag);for(const [k,v]of Object.entries(attrs))n.setAttribute(k,v);if(text)n.textContent=text;svg.append(n);};
 shape('rect',{width:800,height:500,fill:'#f3f5f2'});for(let x=0;x<800;x+=40)shape('path',{d:`M${x} 0V500`,stroke:'#dce1dc'});for(let y=0;y<500;y+=40)shape('path',{d:`M0 ${y}H800`,stroke:'#dce1dc'});
 for(const r of plan.runs){if(!r.points.length)continue;shape('polyline',{points:r.points.map(p=>p.join(',')).join(' '),fill:'none',stroke:'#d7192b','stroke-width':4});r.points.forEach(p=>shape('circle',{cx:p[0],cy:p[1],r:5,fill:'#d7192b'}));}
 for(const g of plan.gates){const a=plan.runs[g.run].points[g.segment],b=plan.runs[g.run].points[g.segment+1],x=a[0]+(b[0]-a[0])*g.t,y=a[1]+(b[1]-a[1])*g.t;shape('rect',{x:x-16,y:y-16,width:32,height:32,rx:3,fill:'#222',stroke:'white','stroke-width':2});shape('text',{x,y:y+6,fill:'white','font-size':18,'text-anchor':'middle'},g.type==='single'?'S':'D');}target.append(svg);
}
export function project(data,target){const p=data.payload||data,pricing=data.pricing;target.replaceChildren();const grid=el('dl',undefined,'quote-facts');const gates=t=>p.plan.gates.filter(g=>g.type===t).length+p.plan.extraGates[t];for(const [label,value]of [['Project',p.address],['Fence',p.options.fence==='panels'?'Panels & stands':p.options.fence==='driven'?'Post-driven chain link':p.options.fence],['Footage',`${totalFeet(p.plan).toFixed(1)} linear ft`],['Rental',`${p.options.months} months`],['Gates',`${gates('single')} single / ${gates('double')} double`],['Requested date',p.installDate||'To be confirmed']]){const row=el('div');row.append(el('dt',label),el('dd',value));grid.append(row);}target.append(grid);const drawing=el('div',undefined,'quote-drawing');draw(p.plan,drawing);target.append(drawing,el('p','Customer scale sketch. Gate symbols show locations, not opening widths. Satellite mapping is not connected yet.','quiet'));
 const amount=el('div',undefined,'quote-price');amount.append(el('span',pricing.review.length?'Known items subtotal · before tax':'Preliminary estimate · before tax'),el('strong',money(pricing.total)));target.append(amount);
 for(const item of pricing.items){const row=el('div',undefined,'quote-line');row.append(el('span',`${item.label} (${item.quantity} × ${money(item.rate)})`),el('strong',money(item.amount)));target.append(row);}
 const ul=el('ul',undefined,'quote-review');pricing.review.forEach(t=>ul.append(el('li',t)));target.append(ul,el('p','Richard must confirm measurements, site conditions, taxes, minimum charges, pricing, and availability before booking.','quiet'));
}
